func alienOrder(_ words: [String]) -> String {
    var adj: [Character: Set<Character>] = [:], indegree: [Character: Int] = [:]
    for w in words { for c in w { adj[c, default: []] = adj[c, default: []]; indegree[c, default: 0] += 0 } }
    for (a, b) in zip(words, words.dropFirst()) {
        if a.count > b.count && a.hasPrefix(b) { return "" }
        for (x, y) in zip(a, b) where x != y {
            if adj[x]!.insert(y).inserted { indegree[y]! += 1 }
            break
        }
    }
    var queue = indegree.filter { $0.value == 0 }.map(\.key), order: [Character] = []
    while let c = queue.popLast() {
        order.append(c)
        for n in adj[c]! { indegree[n]! -= 1; if indegree[n] == 0 { queue.append(n) } }
    }
    return order.count == indegree.count ? String(order) : ""
}
